using FamilyVeda.Application.Common;
using FamilyVeda.Application.Portal;
using FamilyVeda.Domain.Clinical;
using FamilyVeda.Domain.Common;
using FamilyVeda.Domain.Identity;
using FamilyVeda.Domain.Portal;
using FamilyVeda.Infrastructure.Persistence;
using FamilyVeda.Infrastructure.Portal;
using FluentAssertions;
using Microsoft.EntityFrameworkCore;

namespace FamilyVeda.UnitTests;

public sealed class FamilyDoctorServiceTests
{
    private static AppDbContext NewDb() =>
        new(new DbContextOptionsBuilder<AppDbContext>().UseInMemoryDatabase(Guid.NewGuid().ToString()).Options);

    [Fact]
    public async Task Request_ByNonHead_Returns404()
    {
        await using var db = NewDb();
        var head = new UserAccount { Email = "head@example.invalid", PasswordHash = "x", DisplayName = "Head", UserType = UserType.FamilyUser };
        var family = new Family { Name = "F", CreatedByUser = head, FamilyCode = "FV-AAA111" };
        var adultUser = new UserAccount { Email = "adult@example.invalid", PasswordHash = "x", DisplayName = "Adult", UserType = UserType.FamilyUser };
        var adultMember = new Member { Family = family, User = adultUser, DisplayName = "Adult", DateOfBirth = new DateOnly(1990, 1, 1), Role = FamilyRole.AdultMember };
        var doctorUser = new UserAccount { Email = "doc@example.invalid", PasswordHash = "x", DisplayName = "Doc", UserType = UserType.Doctor };
        var doctor = new Doctor { User = doctorUser, RegistrationNumberHash = "h", RegistrationNumberLastFour = "1234", VerificationStatus = VerificationStatus.Verified };
        db.AddRange(head, family, adultUser, adultMember, doctorUser, doctor);
        await db.SaveChangesAsync();
        var service = new FamilyDoctorService(db, new StubCurrentUser(adultUser.Id, UserType.FamilyUser));

        var act = () => service.RequestAsync(family.Id, new CreateDoctorRequest(doctor.Id, null), CancellationToken.None);

        await act.Should().ThrowAsync<NotFoundException>();
    }

    [Fact]
    public async Task Accept_EndsPreviousPrimaryAssignment_AndDoesNotDeleteIt()
    {
        await using var db = NewDb();
        var head = new UserAccount { Email = "head@example.invalid", PasswordHash = "x", DisplayName = "Head", UserType = UserType.FamilyUser };
        var family = new Family { Name = "F", CreatedByUser = head, FamilyCode = "FV-BBB222" };
        var oldDoctorUser = new UserAccount { Email = "old@example.invalid", PasswordHash = "x", DisplayName = "Old Doc", UserType = UserType.Doctor };
        var oldDoctor = new Doctor { User = oldDoctorUser, RegistrationNumberHash = "h1", RegistrationNumberLastFour = "1111", VerificationStatus = VerificationStatus.Verified };
        var newDoctorUser = new UserAccount { Email = "new@example.invalid", PasswordHash = "x", DisplayName = "New Doc", UserType = UserType.Doctor };
        var newDoctor = new Doctor { User = newDoctorUser, RegistrationNumberHash = "h2", RegistrationNumberLastFour = "2222", VerificationStatus = VerificationStatus.Verified };
        var existingAssignment = new FamilyDoctorAssignment { Family = family, Doctor = oldDoctor, IsPrimary = true };
        db.AddRange(head, family, oldDoctorUser, oldDoctor, newDoctorUser, newDoctor, existingAssignment);
        await db.SaveChangesAsync();

        var headService = new FamilyDoctorService(db, new StubCurrentUser(head.Id, UserType.FamilyUser));
        var request = await headService.RequestAsync(family.Id, new CreateDoctorRequest(newDoctor.Id, null), CancellationToken.None);

        var doctorService = new FamilyDoctorService(db, new StubCurrentUser(newDoctorUser.Id, UserType.Doctor));
        await doctorService.AcceptAsync(request.Id, CancellationToken.None);

        var oldAssignment = await db.FamilyDoctorAssignments.SingleAsync(x => x.DoctorId == oldDoctor.Id);
        oldAssignment.EndedAt.Should().NotBeNull();
        (await db.FamilyDoctorAssignments.CountAsync()).Should().Be(2);
        var newAssignment = await db.FamilyDoctorAssignments.SingleAsync(x => x.DoctorId == newDoctor.Id);
        newAssignment.IsPrimary.Should().BeTrue();
        newAssignment.EndedAt.Should().BeNull();
    }

    [Fact]
    public async Task Request_AlreadyAssignedDoctor_ReturnsConflict()
    {
        await using var db = NewDb();
        var head = new UserAccount { Email = "head-current@example.invalid", PasswordHash = "x", DisplayName = "Head", UserType = UserType.FamilyUser };
        var family = new Family { Name = "F", CreatedByUser = head, FamilyCode = "FV-CCC222" };
        var doctorUser = new UserAccount { Email = "doc-current@example.invalid", PasswordHash = "x", DisplayName = "Doc", UserType = UserType.Doctor };
        var doctor = new Doctor { User = doctorUser, RegistrationNumberHash = "h", RegistrationNumberLastFour = "0000", VerificationStatus = VerificationStatus.Verified };
        db.AddRange(head, family, doctorUser, doctor, new FamilyDoctorAssignment { Family = family, Doctor = doctor, IsPrimary = true });
        await db.SaveChangesAsync();

        var service = new FamilyDoctorService(db, new StubCurrentUser(head.Id, UserType.FamilyUser));
        var act = () => service.RequestAsync(family.Id, new CreateDoctorRequest(doctor.Id, null), CancellationToken.None);

